// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzzed params: attacker is any address that may try to call transferOwnership;
    // newOwner is any candidate owner address to set
    function testFuzz_property(address attacker, address newOwner) public {
        // keep wide: attacker and newOwner can be any addresses
        // Ensure attacker is not the initial owner (which is zero address since owner uninitialized)
        // In the reference contract, owner defaults to address(0). Only address(0) can call onlyOwner.
        // A real EOA cannot be address(0), so any non-zero attacker must fail to change ownership.
        vm.assume(attacker != address(0));

        // Record owner before
        address ownerBefore = c.owner();

        // Try to call transferOwnership as attacker
        bool ok;
        vm.prank(attacker);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, owner should remain unchanged for ALL inputs in the correct contract
        address ownerAfter = c.owner();

        // General invariant: if caller is not the current owner, transferOwnership must NOT change owner.
        // Since we ensured attacker != address(0) and initial owner is address(0), attacker is non-owner.
        // Thus reference C will keep owner equal; the mutant that removed the require will allow change
        assertTrue(ownerAfter == ownerBefore);
    }
}
